    "formula": "(+) A + 是 + B / A + 有 + B / A + 在 + Địa điểm | (-) A + 不是 + B / A + 没有 + B / A + 不在 + Địa điểm | (?) A + 是/有/在 + ... + 吗？",
    "summary": "Ba động từ cốt lõi nhất ở HSK 1 nhưng rất hay bị dùng lẫn lộn. '是' (shì) dùng để nối chủ ngữ với danh từ định nghĩa, nghề nghiệp hoặc quốc tịch, tuyệt đối không nối trực tiếp với tính từ. '有' (yǒu) diễn tả sự sở hữu hoặc tồn tại, phủ định luôn dùng '没有' (méiyǒu), không dùng '不有'. '在' (zài) diễn tả vị trí hiện diện tại một nơi chốn hoặc đứng trước động từ làm trạng ngữ chỉ địa điểm.",
    "deepNotesHtml": "<p><strong>1. Tư duy Việt–Trung:</strong> Tiếng Việt dùng từ <em>“là”</em> cho cả danh từ lẫn tính từ (ví dụ: <em>“Tôi là học sinh”</em> và <em>“Hôm nay là rất nóng”</em> nói tắt), nhưng tiếng Trung phân tách rạch ròi: <code>是</code> (shì — là) chỉ nối danh từ với danh từ, còn tính từ vị ngữ phải dùng phó từ mức độ như <code>很</code> (hěn — rất) chứ không dùng <code>是</code>.</p><p><strong>2. Thang lắp ghép câu từ dễ đến khó:</strong></p><ul><li><em>Cấp 1 (Định nghĩa):</em> <code>我是学生</code> (Wǒ shì xuésheng — Tôi là học sinh) → Phủ định: <code>我不是老师</code> (Wǒ bú shì lǎoshī — Tôi không phải giáo viên).</li><li><em>Cấp 2 (Sở hữu &amp; Tồn tại):</em> <code>我有一本书</code> (Wǒ yǒu yì běn shū — Tôi có một quyển sách) → Tồn tại: <code>桌子上有一支笔</code> (Zhuōzi shàng yǒu yì zhī bǐ — Trên bàn có một cây bút).</li><li><em>Cấp 3 (Vị trí &amp; Hành động tại nơi chốn):</em> <code>我在学校</code> (Wǒ zài xuéxiào — Tôi ở trường) → Mở rộng hành động: <code>我在图书馆看书</code> (Wǒ zài túshūguǎn kàn shū — Tôi đọc sách ở thư viện).</li></ul><p><strong>3. Bẫy thi HSK:</strong> Luôn nhớ <code>没有</code> (méiyǒu — không có) là cặp phủ định duy nhất của <code>有</code> (yǒu); khi câu vừa có địa điểm vừa có hành động thì cụm <strong><code>在</code> + Địa điểm</strong> phải đặt trước động từ chính.</p>",
