    "id": "hsk1_de_pos",
    "level": 1,
    "category": "Phó từ & Hư từ",
    "title": "Trợ từ kết cấu 的 & Quy tắc Định ngữ",
    "formula": "(+) Định ngữ + 的 + Danh từ trung tâm | (-) Không + 的 (khi quan hệ ruột thịt/tổ chức) | (?) 谁的 + Danh từ？ / Định ngữ + 的 + Danh từ + 吗？",
    "summary": "Trong tiếng Trung, thành phần bổ nghĩa (Định ngữ) luôn đứng trước danh từ chính, ngược hoàn toàn với tiếng Việt. '的' (de) đóng vai trò cầu nối giữa định ngữ và danh từ trung tâm. Có thể lược bỏ '的' khi diễn tả quan hệ thân thuộc gắn bó hoặc quốc tịch, tổ chức, nhưng bắt buộc giữ '的' khi định ngữ là tính từ hai âm tiết hoặc cụm động từ.",
    "deepNotesHtml": "<p><strong>1. Tư duy Việt–Trung:</strong> Tiếng Việt nói <em>“quyển sách <u>của tôi</u>”</em> hay <em>“người <u>mặc áo đỏ</u>”</em> với danh từ chính đứng trước, phần miêu tả đứng sau. Tiếng Trung đảo ngược 180 độ: toàn bộ phần miêu tả hay sở hữu phải xếp lên trước chữ <code>的</code> (de — của/mà), danh từ chính chốt ở cuối cụm.</p><p><strong>2. Thang lắp ghép câu từ dễ đến khó:</strong></p><ul><li><em>Cấp 1 (Sở hữu đơn giản):</em> <code>我的手机</code> (Wǒ de shǒujī — điện thoại của tôi) · Lược <code>的</code> với người thân: <code>我妈妈</code> (wǒ māma — mẹ tôi), <code>我们学校</code> (wǒmen xuéxiào — trường chúng tôi).</li><li><em>Cấp 2 (Tính từ làm định ngữ):</em> <code>很好的老师</code> (hěn hǎo de lǎoshī — giáo viên rất tốt), <code>漂亮的衣服</code> (piàoliang de yīfu — quần áo đẹp).</li><li><em>Cấp 3 (Cụm động-tân làm định ngữ):</em> <code>我昨天买的书</code> (wǒ zuótiān mǎi de shū — quyển sách tôi mua hôm qua) → Ghép cả câu: <code>穿红衣服的人是我姐姐</code> (Chuān hóng yīfu de rén shì wǒ jiějie — Người mặc áo đỏ là chị gái tôi).</li></ul><p><strong>3. Bẫy thi HSK:</strong> Khi hỏi sở hữu dùng <code>这是谁的书？</code> (Zhè shì shéi de shū? — Đây là sách của ai?), không bao giờ đặt <code>书</code> lên trước <code>谁</code>. Ngoài ra, danh từ phía sau đã rõ ngữ cảnh có thể lược bỏ tạo thành cụm chữ <code>的</code> như <code>这本是我的</code> (Zhè běn shì wǒ de — Quyển này là của tôi).</p>",
