      "❌ 现在是两十二点 (xiànzài shì liǎngshí'èr diǎn) → ✅ 现在是十二点 (shí'èr diǎn) / 二十二号 (èrshí'èr hào) (Hàng chục và hàng đơn vị luôn dùng 二, không bao giờ dùng 两十).",
      "❌ 我去过中国二次 (wǒ qù guo Zhōngguó èr cì) → ✅ 我去过中国两次 (wǒ qù guo Zhōngguó liǎng cì) (Trước lượng từ động lượng 次 phải dùng 两, nhưng 'lần thứ hai' là 第二次)."
