      "❌ 书在桌子 (shū zài zhuōzi) → ✅ 书在桌子上 (shū zài zhuōzi shàng) (Đồ vật không phải nơi chốn, phải thêm 上/里 mới dùng được sau 在).",
      "❌ 有一只小狗在桌子下面 → ✅ 桌子下面有一只小狗 / 小狗在桌子下面 (Vật chưa xác định mới nhắc tới đặt sau 有 ở cuối câu; vật đã xác định đặt đầu câu trước 在)."
