      "❌ 我是明天去上海的 (wǒ shì míngtiān qù Shànghǎi de) → ✅ 我明天去上海 / 我是昨天去上海的 (Khung 是...的 chỉ nhấn mạnh việc đã xảy ra ở quá khứ, không dùng cho tương lai 明天).",
      "❌ 我是在北京认识的他 → ✅ 我是在北京认识他的 (Nếu tân ngữ là đại từ nhân xưng 他/她 thì đặt trước 的)."
