      "❌ 我想喝有点儿咖啡 (wǒ xiǎng hē yǒudiǎnr kāfēi) → ✅ 我想喝一点儿咖啡 (wǒ xiǎng hē yìdiǎnr kāfēi) (Đứng sau động từ và trước danh từ dùng 一点儿).",
      "❌ 他一点儿很高 (tā yìdiǎnr hěn gāo) → ✅ 他比我高一点儿 (tā bǐ wǒ gāo yìdiǎnr) (一点儿 đứng SAU tính từ để chỉ mức độ chênh lệch)."
