        "py": "Wǒ gāngcái dǎ guo tā liǎng cì diànhuà, kěshì tā dōu méi jiē.",
        "vi": "Vừa nãy tôi đã gọi điện cho anh ấy hai lần, nhưng anh ấy đều không nghe máy."
