      "❌ 这篇文章我只看了一趟 (zhè piān wénzhāng wǒ zhǐ kàn le yí tàng) → ✅ 这篇文章我只看了一遍 (zhè piān wénzhāng wǒ zhǐ kàn le yí biàn) (Đọc trọn vẹn một bài văn từ đầu đến cuối dùng 遍, 趟 dùng cho đi lại).",
      "❌ 我去过两次了北京 (wǒ qù guo liǎng cì le Běijīng) → ✅ 我去过北京两次了 / 我去过两次北京 (wǒ qù guo Běijīng liǎng cì le) (Danh từ địa điểm 北京 đứng trước 两次 hoặc cuối câu đều được, không chen 了 vào trước 北京)."
