      "❌ 他不但喜欢看书，但是也喜欢运动 → ✅ 他不但喜欢看书，而且也喜欢运动 (Cặp tăng tiến phải là 不但...而且..., không ghép 不但 với 但是).",
      "❌ 这个房间既大又没有漂亮 → ✅ 这个房间既不大也不漂亮 / 既干净又漂亮 (既...又... nối hai vế đồng chất khẳng định với khẳng định, hoặc 既不...也不...)."
