      "❌ 我以前学汉语，以后我去了中国 → ✅ 我以前学过汉语，后来去了中国 (Kể trình tự sự việc đã xảy ra ở quá khứ dùng 后来, không dùng 以后).",
      "❌ 我先去银行，又去超市 (khi nói kế hoạch chưa xảy ra) → ✅ 我先去银行，再去超市 (Hành động nối tiếp chưa xảy ra dùng 先...再..., không dùng 又)."
